        },
        {
            "function_name": "<function_name_2>",
            "code": "<original_function_code_2>",
            "vulnerability": "<short_vulnera_desc_2>",
            "reason": "<reason_2>"
        }
    ]
}
Output 3 most severe vulnerabilities.
If no vulnerability is detected, you should only output in this json format {"output_list": []}.
Smart contract code:

pragma solidity ^0.7.6; library SafeMath { function tryAdd(uint256 a, uint256 b) internal pure returns (bool, uint256) { uint256 c = a + b; if (c < a) return (false, 0); return (true, c); } function trySub(uint256 a, uint256 b) internal pure returns (bool, uint256) { if (b > a) return (false, 0); return (true, a - b); } function tryMul(uint256 a, uint256 b) internal pure returns (bool, uint256) { if (a == 0) return (true, 0); uint256 c = a * b; if (c / a != b) return (false, 0); return (true, c); } function tryDiv(uint256 a, uint256 b) internal pure returns (bool, uint256) { if (b == 0) return (false, 0); return (true, a / b); } function tryMod(uint256 a, uint256 b) internal pure returns (bool, uint256) { if (b == 0) return (false, 0); return (true, a % b); } function add(uint256 a, uint256 b) internal pure returns (uint256) { uint256 c = a + b; require(c >= a, "SafeMath: addition overflow"); return c; } function sub(uint256 a, uint256 b) internal pure returns (uint256) { require(b <= a, "SafeMath: subtraction overflow"); return a - b; } function mul(uint256 a, uint256 b) internal pure returns (uint256) { if (a == 0) return 0; uint256 c = a * b; require(c / a == b, "SafeMath: multiplication overflow"); return c; } function div(uint256 a, uint256 b) internal pure returns (uint256) { require(b > 0, "SafeMath: division by zero"); return a / b; } function mod(uint256 a, uint256 b) internal pure returns (uint256) { require(b > 0, "SafeMath: modulo by zero"); return a % b; } function sub(uint256 a, uint256 b, string memory errorMessage) internal pure returns (uint256) { require(b <= a, errorMessage); return a - b; } function div(uint256 a, uint256 b, string memory errorMessage) internal pure returns (uint256) { require(b > 0, errorMessage); return a / b; } function mod(uint256 a, uint256 b, string memory errorMessage) internal pure returns (uint256) { require(b > 0, errorMessage); return a % b; } } interface IERC20 { function totalSupply() external view returns (uint256); function balanceOf(address account) external view returns (uint256); function transfer(address recipient, uint256 amount) external returns (bool); function allowance(address owner, address spender) external view returns (uint256); function approve(address spender, uint256 amount) external returns (bool); function transferFrom(address sender, address recipient, uint256 amount) external returns (bool); event Transfer(address indexed from, address indexed to, uint256 value); event Approval(address indexed owner, address indexed spender, uint256 value); } abstract contract Context { function _msgSender() internal view virtual returns (address payable) { return msg.sender; } function _msgData() internal view virtual returns (bytes memory) { this; return msg.data; } } contract ERC20 is Context, IERC20 { using SafeMath for uint256; mapping (address => uint256) private _balances; mapping (address => mapping (address => uint256)) private _allowances; uint256 private _totalSupply; string private _name; string private _symbol; uint8 private _decimals; constructor (string memory name_, string memory symbol_) public { _name = name_; _symbol = symbol_; _decimals = 18; } function name() public view virtual returns (string memory) { return _name; } function symbol() public view virtual returns (string memory) { return _symbol; } function decimals() public view virtual returns (uint8) { return _decimals; } function totalSupply() public view virtual override returns (uint256) { return _totalSupply; } function balanceOf(address account) public view virtual override returns (uint256) { return _balances[account]; } function transfer(address recipient, uint256 amount) public virtual override returns (bool) { _transfer(_msgSender(), recipient, amount); return true; } function allowance(address owner, address spender) public view virtual override returns (uint256) { return _allowances[owner][spender]; } function approve(address spender, uint256 amount) public virtual override returns (bool) { _approve(_msgSender(), spender, amount); return true; } function transferFrom(address sender, address recipient, uint256 amount) public virtual override returns (bool) { _transfer(sender, recipient, amount); _approve(sender, _msgSender(), _allowances[sender][_msgSender()].sub(amount, "ERC20: transfer amount exceeds allowance")); return true; } function increaseAllowance(address spender, uint256 addedValue) public virtual returns (bool) { _approve(_msgSender(), spender, _allowances[_msgSender()][spender].add(addedValue)); return true; } function decreaseAllowance(address spender, uint256 subtractedValue) public virtual returns (bool) { _approve(_msgSender(), spender, _allowances[_msgSender()][spender].sub(subtractedValue, "ERC20: decreased allowance below zero")); return true; } function _transfer(address sender, address recipient, uint256 amount) internal virtual { require(sender != address(0), "ERC20: transfer from the zero address"); require(recipient != address(0), "ERC20: transfer to the zero address"); _beforeTokenTransfer(sender, recipient, amount); _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance"); _balances[recipient] = _balances[recipient].add(amount); emit Transfer(sender, recipient, amount); } function _mint(address account, uint256 amount) internal virtual { require(account != address(0), "ERC20: mint to the zero address"); _beforeTokenTransfer(address(0), account, amount); _totalSupply = _totalSupply.add(amount); _balances[account] = _balances[account].add(amount); emit Transfer(address(0), account, amount); } function _burn(address account, uint256 amount) internal virtual { require(account != address(0), "ERC20: burn from the zero address"); _beforeTokenTransfer(account, address(0), amount); _balances[account] = _balances[account].sub(amount, "ERC20: burn amount exceeds balance"); _totalSupply = _totalSupply.sub(amount); emit Transfer(account, address(0), amount); } function _approve(address owner, address spender, uint256 amount) internal virtual { require(owner != address(0), "ERC20: approve from the zero address"); require(spender != address(0), "ERC20: approve to the zero address"); _allowances[owner][spender] = amount; emit Approval(owner, spender, amount); } function _setupDecimals(uint8 decimals_) internal virtual { _decimals = decimals_; } function _beforeTokenTransfer(address from, address to, uint256 amount) internal virtual { } } contract DSAuthEvents { event LogSetAuthority(address indexed authority); event LogSetOwner(address indexed owner); } contract DSAuth is DSAuthEvents { address public owner; function setOwner(address owner_) external auth { owner = owner_; emit LogSetOwner(owner); } modifier auth() { require(isAuthorized(msg.sender), "ds-auth-unauthorized"); _; } function isAuthorized(address src) internal view returns (bool) { if (src == address(this)) { return true; } else if (src == owner) { return true; } else { return false; } } } contract DSMath { function add(uint256 x, uint256 y) internal pure returns (uint256 z) { require((z = x + y) >= x, "ds-math-add-overflow"); } function sub(uint256 x, uint256 y) internal pure returns (uint256 z) { require((z = x - y) <= x, "ds-math-sub-underflow"); } function mul(uint256 x, uint256 y) internal pure returns (uint256 z) { require(y == 0 || (z = x * y) / y == x, "ds-math-mul-overflow"); } function min(uint256 x, uint256 y) internal pure returns (uint256 z) { return x <= y ? x : y; } function max(uint256 x, uint256 y) internal pure returns (uint256 z) { return x >= y ? x : y; } function imin(int256 x, int256 y) internal pure returns (int256 z) { return x <= y ? x : y; } function imax(int256 x, int256 y) internal pure returns (int256 z) { return x >= y ? x : y; } uint256 constant WAD = 10**18; uint256 constant RAY = 10**27; function wmul(uint256 x, uint256 y) internal pure returns (uint256 z) { z = add(mul(x, y), WAD / 2) / WAD; } function rmul(uint256 x, uint256 y) internal pure returns (uint256 z) { z = add(mul(x, y), RAY / 2) / RAY; } function wdiv(uint256 x, uint256 y) internal pure returns (uint256 z) { z = add(mul(x, WAD), y / 2) / y; } function rdiv(uint256 x, uint256 y) internal pure returns (uint256 z) { z = add(mul(x, RAY), y / 2) / y; } } contract EventfulMarket { event LogItemUpdate(uint256 id); event LogTrade( uint256 pay_amt, address indexed pay_gem, uint256 buy_amt, address indexed buy_gem ); event LogMake( bytes32 indexed id, bytes32 indexed pair, address indexed maker, ERC20 pay_gem, ERC20 buy_gem, uint128 pay_amt, uint128 buy_amt, uint64 timestamp ); event LogBump( bytes32 indexed id, bytes32 indexed pair, address indexed maker, ERC20 pay_gem, ERC20 buy_gem, uint128 pay_amt, uint128 buy_amt, uint64 timestamp ); event LogTake( bytes32 id, bytes32 indexed pair, address indexed maker, ERC20 pay_gem, ERC20 buy_gem, address indexed taker, uint128 take_amt, uint128 give_amt, uint64 timestamp ); event LogKill( bytes32 indexed id, bytes32 indexed pair, address indexed maker, ERC20 pay_gem, ERC20 buy_gem, uint128 pay_amt, uint128 buy_amt, uint64 timestamp ); event LogInt(string lol, uint256 input); event FeeTake( bytes32 indexed id, bytes32 indexed pair, ERC20 asset, address indexed taker, address feeTo, uint256 feeAmt, uint64 timestamp ); event OfferDeleted(uint256 id); } contract SimpleMarket is EventfulMarket, DSMath { uint256 public last_offer_id; mapping(uint256 => OfferInfo) public offers; bool locked; uint256 internal feeBPS; address internal feeTo; struct OfferInfo { uint256 pay_amt; ERC20 pay_gem; uint256 buy_amt; ERC20 buy_gem; address owner; uint64 timestamp; } modifier can_buy(uint256 id) virtual { require(isActive(id)); _; } modifier can_cancel(uint256 id) virtual { require(isActive(id)); require(getOwner(id) == msg.sender); _; } modifier can_offer() virtual { _; } modifier synchronized() { require(!locked); locked = true; _; locked = false; } function isActive(uint256 id) public view returns (bool active) { return offers[id].timestamp > 0; } function getOwner(uint256 id) public view returns (address owner) { return offers[id].owner; } function getOffer(uint256 id) public view returns ( uint256, ERC20, uint256, ERC20 ) { OfferInfo memory _offer = offers[id]; return (_offer.pay_amt, _offer.pay_gem, _offer.buy_amt, _offer.buy_gem); } function bump(bytes32 id_) external can_buy(uint256(id_)) { uint256 id = uint256(id_); emit LogBump( id_, keccak256(abi.encodePacked(offers[id].pay_gem, offers[id].buy_gem)), offers[id].owner, offers[id].pay_gem, offers[id].buy_gem, uint128(offers[id].pay_amt), uint128(offers[id].buy_amt), offers[id].timestamp ); } function buy(uint256 id, uint256 quantity) public virtual can_buy(id) synchronized returns (bool) { OfferInfo memory _offer = offers[id]; uint256 spend = mul(quantity, _offer.buy_amt) / _offer.pay_amt; require(uint128(spend) == spend, "spend is not an int"); require(uint128(quantity) == quantity, "quantity is not an int"); if ( quantity == 0 || spend == 0 || quantity > _offer.pay_amt || spend > _offer.buy_amt ) { return false; } uint256 fee = mul(spend, feeBPS) / 10000; require( _offer.buy_gem.transferFrom(msg.sender, feeTo, fee), "Insufficient funds to cover fee" ); offers[id].pay_amt = sub(_offer.pay_amt, quantity); offers[id].buy_amt = sub(_offer.buy_amt, spend); require( _offer.buy_gem.transferFrom(msg.sender, _offer.owner, spend), "_offer.buy_gem.transferFrom(msg.sender, _offer.owner, spend) failed - check that you can pay the fee" ); require( _offer.pay_gem.transfer(msg.sender, quantity), "_offer.pay_gem.transfer(msg.sender, quantity) failed" ); emit LogItemUpdate(id); emit LogTake( bytes32(id), keccak256(abi.encodePacked(_offer.pay_gem, _offer.buy_gem)), _offer.owner, _offer.pay_gem, _offer.buy_gem, msg.sender, uint128(quantity), uint128(spend), uint64(block.timestamp) ); emit FeeTake( bytes32(id), keccak256(abi.encodePacked(_offer.pay_gem, _offer.buy_gem)), _offer.buy_gem, msg.sender, feeTo, fee, uint64(block.timestamp) ); emit LogTrade( quantity, address(_offer.pay_gem), spend, address(_offer.buy_gem) ); if (offers[id].pay_amt == 0) { delete offers[id]; emit OfferDeleted(id); } return true; } function cancel(uint256 id) public virtual can_cancel(id) synchronized returns (bool success) { OfferInfo memory _offer = offers[id]; delete offers[id]; require(_offer.pay_gem.transfer(_offer.owner, _offer.pay_amt)); emit LogItemUpdate(id); emit LogKill( bytes32(id), keccak256(abi.encodePacked(_offer.pay_gem, _offer.buy_gem)), _offer.owner, _offer.pay_gem, _offer.buy_gem, uint128(_offer.pay_amt), uint128(_offer.buy_amt), uint64(block.timestamp) ); success = true; } function kill(bytes32 id) external virtual { require(cancel(uint256(id))); } function make( ERC20 pay_gem, ERC20 buy_gem, uint128 pay_amt, uint128 buy_amt ) external virtual returns (bytes32 id) { return bytes32(offer(pay_amt, pay_gem, buy_amt, buy_gem)); } function offer( uint256 pay_amt, ERC20 pay_gem, uint256 buy_amt, ERC20 buy_gem ) public virtual can_offer synchronized returns (uint256 id) { require(uint128(pay_amt) == pay_amt); require(uint128(buy_amt) == buy_amt); require(pay_amt > 0); require(pay_gem != ERC20(0x0)); require(buy_amt > 0); require(buy_gem != ERC20(0x0)); require(pay_gem != buy_gem); OfferInfo memory info; info.pay_amt = pay_amt; info.pay_gem = pay_gem; info.buy_amt = buy_amt; info.buy_gem = buy_gem; info.owner = msg.sender; info.timestamp = uint64(block.timestamp); id = _next_id(); offers[id] = info; require(pay_gem.transferFrom(msg.sender, address(this), pay_amt)); emit LogItemUpdate(id); emit LogMake( bytes32(id), keccak256(abi.encodePacked(pay_gem, buy_gem)), msg.sender, pay_gem, buy_gem, uint128(pay_amt), uint128(buy_amt), uint64(block.timestamp) ); } function take(bytes32 id, uint128 maxTakeAmount) external virtual { require(buy(uint256(id), maxTakeAmount)); } function _next_id() internal returns (uint256) { last_offer_id++; return last_offer_id; } function getFeeBPS() internal view returns (uint256) { return feeBPS; } } contract ExpiringMarket is DSAuth, SimpleMarket { bool public stopped; modifier can_offer() override { require(!isClosed()); _; } modifier can_buy(uint256 id) override { require(isActive(id)); require(!isClosed()); _; } modifier can_cancel(uint256 id) virtual override { require(isActive(id)); require((msg.sender == getOwner(id)) || isClosed()); _; } function isClosed() public pure returns (bool closed) { return false; } function getTime() public view returns (uint64) { return uint64(block.timestamp); } function stop() external auth { stopped = true; } } contract DSNote { event LogNote( bytes4 indexed sig, address indexed guy, bytes32 indexed foo, bytes32 indexed bar, uint256 wad, bytes fax ) anonymous; modifier note() { bytes32 foo; bytes32 bar; uint256 wad; assembly { foo := calldataload(4) bar := calldataload(36) wad := callvalue() } emit LogNote(msg.sig, msg.sender, foo, bar, wad, msg.data); _; } } contract MatchingEvents { event LogBuyEnabled(bool isEnabled); event LogMinSell(address pay_gem, uint256 min_amount); event LogMatchingEnabled(bool isEnabled); event LogUnsortedOffer(uint256 id); event LogSortedOffer(uint256 id); event LogInsert(address keeper, uint256 id); event LogDelete(address keeper, uint256 id); event LogMatch(uint256 id, uint256 amount); } contract RubiconMarket is MatchingEvents, ExpiringMarket, DSNote { bool public buyEnabled = true; bool public matchingEnabled = true; bool public initialized; bool public AqueductDistributionLive; address public AqueductAddress; struct sortInfo { uint256 next; uint256 prev; uint256 delb; } mapping(uint256 => sortInfo) public _rank; mapping(address => mapping(address => uint256)) public _best; mapping(address => mapping(address => uint256)) public _span; mapping(address => uint256) public _dust; mapping(uint256 => uint256) public _near; uint256 public _head; uint256 public dustId; function initialize(bool _live, address _feeTo) public { require(!initialized, "contract is already initialized"); AqueductDistributionLive = _live; feeTo = _feeTo; owner = msg.sender; emit LogSetOwner(msg.sender); feeBPS = 20; initialized = true; matchingEnabled = true; buyEnabled = true; } modifier can_cancel(uint256 id) override { require(isActive(id), "Offer was deleted or taken, or never existed."); require( isClosed() || msg.sender == getOwner(id) || id == dustId, "Offer can not be cancelled because user is not owner, and market is open, and offer sells required amount of tokens." ); _; } function make( ERC20 pay_gem, ERC20 buy_gem, uint128 pay_amt, uint128 buy_amt ) public override returns (bytes32) { return bytes32(offer(pay_amt, pay_gem, buy_amt, buy_gem)); } function take(bytes32 id, uint128 maxTakeAmount) public override { require(buy(uint256(id), maxTakeAmount)); } function kill(bytes32 id) external override { require(cancel(uint256(id))); } function offer( uint256 pay_amt, ERC20 pay_gem, uint256 buy_amt, ERC20 buy_gem ) public override returns (uint256) { require(!locked, "Reentrancy attempt"); function(uint256, ERC20, uint256, ERC20) returns (uint256) fn = matchingEnabled ? _offeru : super.offer; return fn(pay_amt, pay_gem, buy_amt, buy_gem); } function offer( uint256 pay_amt, ERC20 pay_gem, uint256 buy_amt, ERC20 buy_gem, uint256 pos ) external can_offer returns (uint256) { return offer(pay_amt, pay_gem, buy_amt, buy_gem, pos, true); } function offer( uint256 pay_amt, ERC20 pay_gem, uint256 buy_amt, ERC20 buy_gem, uint256 pos, bool matching ) public can_offer returns (uint256) { require(!locked, "Reentrancy attempt"); require(_dust[address(pay_gem)] <= pay_amt); if (matchingEnabled) { return _matcho(pay_amt, pay_gem, buy_amt, buy_gem, pos, matching); } return super.offer(pay_amt, pay_gem, buy_amt, buy_gem); } function buy(uint256 id, uint256 amount) public override can_buy(id) returns (bool) { require(!locked, "Reentrancy attempt"); if (AqueductDistributionLive) { IAqueduct(AqueductAddress).distributeToMakerAndTaker( getOwner(id), msg.sender ); } function(uint256, uint256) returns (bool) fn = matchingEnabled ? _buys : super.buy; return fn(id, amount); } function cancel(uint256 id) public override can_cancel(id) returns (bool success) { require(!locked, "Reentrancy attempt"); if (matchingEnabled) { if (isOfferSorted(id)) { require(_unsort(id)); } else { require(_hide(id)); } } return super.cancel(id); } function insert( uint256 id, uint256 pos ) public returns (bool) { require(!locked, "Reentrancy attempt"); require(!isOfferSorted(id)); require(isActive(id)); _hide(id); _sort(id, pos); emit LogInsert(msg.sender, id); return true; } function del_rank(uint256 id) external returns (bool) { require(!locked, "Reentrancy attempt"); require( !isActive(id) && _rank[id].delb != 0 && _rank[id].delb < block.number - 10 ); delete _rank[id]; emit LogDelete(msg.sender, id); return true; } function setMinSell( ERC20 pay_gem, uint256 dust ) external auth note returns (bool) { _dust[address(pay_gem)] = dust; emit LogMinSell(address(pay_gem), dust); return true; } function getMinSell( ERC20 pay_gem ) external view returns (uint256) { return _dust[address(pay_gem)]; } function setBuyEnabled(bool buyEnabled_) external auth returns (bool) { buyEnabled = buyEnabled_; emit LogBuyEnabled(buyEnabled); return true; } function setMatchingEnabled(bool matchingEnabled_) external auth returns (bool) { matchingEnabled = matchingEnabled_; emit LogMatchingEnabled(matchingEnabled); return true; } function getBestOffer(ERC20 sell_gem, ERC20 buy_gem) public view returns (uint256) { return _best[address(sell_gem)][address(buy_gem)]; } function getWorseOffer(uint256 id) public view returns (uint256) { return _rank[id].prev; } function getBetterOffer(uint256 id) external view returns (uint256) { return _rank[id].next; } function getOfferCount(ERC20 sell_gem, ERC20 buy_gem) public view returns (uint256) { return _span[address(sell_gem)][address(buy_gem)]; } function getFirstUnsortedOffer() public view returns (uint256) { return _head; } function getNextUnsortedOffer(uint256 id) public view returns (ui